def do_algebra(operator, operand):
    result = operand[0]
    for op, val in zip(operator, operand[1:]):
        if op == '+':
            result += val
        elif op == '-':
            result -= val
        elif op == '*':
            result *= val
        elif op == '//':
            result //= val
        elif op == '**':
            result **= val
    return result
